select sum(spend) as total_spend
from fct_marketing_spend
where spend_date >= '2026-04-01' and spend_date <= '2026-04-30';

select count(*) as subscriptions_started
from subscription
where started_date >= '2026-03-01' and started_date < '2026-04-01';

select sum(total_created) as total_created from (
  select count(*) as total_created
  from dim_habit h
) t; select count(*) as total_habits_ever from dim_habits;
